import sys, json, asyncio, re, uuid, os
from aiohttp import web, WSMsgType
import core
NODE=int(sys.argv[sys.argv.index('--node')+1]) if '--node' in sys.argv else 0
def json_error(status,msg): return web.json_response({'error':msg},status=status)
async def read_json(r):
    try: return await r.json()
    except: return None
def require_user(r):
    h=r.headers.get('Authorization','')
    return core.user_for_token(h[7:] if h.startswith('Bearer ') else None)
def U(u): return core.user_to_json(u)
def C(r): return dict(r) if r else None
def memberships(uid,wid):
    c=core.connect(); x=c.execute('SELECT c.* FROM channels c JOIN channel_members m ON m.channel_id=c.id WHERE m.user_id=? AND c.workspace_id=? ORDER BY c.id',(uid,wid)).fetchall(); c.close(); return [C(a) for a in x]
def msg(r):
    c=core.connect(); au=c.execute('SELECT * FROM users WHERE id=?',(r['author_id'],)).fetchone()
    rs=c.execute('SELECT emoji,COUNT(*) n,GROUP_CONCAT(user_id) ids FROM reactions WHERE message_id=? GROUP BY emoji',(r['id'],)).fetchall(); c.close()
    return {'id':r['id'],'channel_id':r['channel_id'],'author_id':r['author_id'],'author':U(au),'body':r['body'],'parent_id':r['parent_id'],'reply_count':0,'created_at':r['created_at'],'edited_at':r['edited_at'],'files':[],'reactions':[{'emoji':x['emoji'],'count':x['n'],'user_ids':[int(i) for i in x['ids'].split(',')]} for x in rs],'mentions':[]}
async def health(r): return web.json_response({'status':'ok','node_id':NODE})
async def register(r):
    d=await read_json(r)
    if not isinstance(d,dict) or not re.fullmatch(r'[A-Za-z0-9_]+',str(d.get('username',''))) or not isinstance(d.get('password'),str) or len(d['password'])<8:return json_error(400,'invalid registration')
    try:
      with core.tx() as c:
        c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(d['username'],core.hash_password(d['password']),d.get('display_name') or d['username']))
        uid=c.lastrowid;t=core.issue_token(c,uid); u=c.execute('SELECT * FROM users WHERE id=?',(uid,)).fetchone()
      return web.json_response({'user':U(u),'token':t},status=201)
    except: return json_error(409,'username already exists')
async def login(r):
    d=await read_json(r); c=core.connect(); u=c.execute('SELECT * FROM users WHERE username=?',(d.get('username') if isinstance(d,dict) else '',)).fetchone(); ok=u and isinstance(d.get('password'),str) and core.verify_password(d['password'],u['password'])
    if not ok:c.close();return json_error(401,'invalid credentials')
    t=core.issue_token(c,u['id']);c.close();return web.json_response({'user':U(u),'token':t})
async def me(r):
    u=require_user(r); return json_error(401,'unauthorized') if not u else web.json_response({'user':U(u)})
async def workspaces(r):
    u=require_user(r)
    if not u:return json_error(401,'unauthorized')
    c=core.connect(); rows=c.execute('SELECT w.* FROM workspaces w JOIN memberships m ON m.workspace_id=w.id WHERE m.user_id=?',(u['id'],)).fetchall();c.close();return web.json_response({'workspaces':[dict(x) for x in rows]})
async def create_workspace(r):
    u=require_user(r)
    if not u:return json_error(401,'unauthorized')
    d=await read_json(r)
    if not isinstance(d,dict) or not re.fullmatch(r'[a-z0-9-]{2,32}',str(d.get('slug',''))) or not d.get('name'):return json_error(400,'invalid workspace')
    try:
      with core.tx() as c:
       c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(d['slug'],d['name'],u['id']));wid=c.lastrowid
       c.execute('INSERT INTO memberships VALUES(?,?,?)',(wid,u['id'],'owner'));c.execute('INSERT INTO channels(workspace_id,name) VALUES(?,?)',(wid,'general'));ch=c.lastrowid;c.execute('INSERT INTO channel_members VALUES(?,?)',(ch,u['id']))
       w=c.execute('SELECT * FROM workspaces WHERE id=?',(wid,)).fetchone(); cc=c.execute('SELECT * FROM channels WHERE id=?',(ch,)).fetchone()
      return web.json_response({'workspace':dict(w),'general_channel':C(cc)},status=201)
    except:return json_error(409,'duplicate workspace')
async def workspace(r):
    u=require_user(r); w=core.get_workspace(r.match_info['slug'])
    if not u:return json_error(401,'unauthorized')
    if not w:return json_error(404,'not found')
    return web.json_response({'workspace':dict(w),'channels':memberships(u['id'],w['id']),'read_state':{}})
async def channels(r):
    u=require_user(r);w=core.get_workspace(r.match_info['slug'])
    if not u:return json_error(401,'unauthorized')
    if not w:return json_error(404,'not found')
    d=await read_json(r)
    if not isinstance(d,dict) or not re.fullmatch(r'[a-z0-9-]{1,32}',str(d.get('name',''))):return json_error(400,'invalid channel')
    if core.member_role(w['id'],u['id']) is None:return json_error(403,'not a member')
    try:
      with core.tx() as c:
       c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],d['name'],int(bool(d.get('is_private'))),d.get('topic','')));i=c.lastrowid;c.execute('INSERT INTO channel_members VALUES(?,?)',(i,u['id']));x=c.execute('SELECT * FROM channels WHERE id=?',(i,)).fetchone())
      return web.json_response({'channel':C(x)},status=201)
    except:return json_error(409,'duplicate channel')
async def join(r):
    u=require_user(r);ch=core.get_channel(r.match_info['id'])
    if not u:return json_error(401,'unauthorized')
    if not ch:return json_error(404,'not found')
    with core.tx() as c:c.execute('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(ch['id'],u['id']))
    return web.json_response({'channel':C(ch)})
async def messages(r):
    u=require_user(r);ch=core.get_channel(r.match_info['id'])
    if not u:return json_error(401,'unauthorized')
    if not ch:return json_error(404,'not found')
    if r.method=='POST':
      d=await read_json(r); body=d.get('body') if isinstance(d,dict) else None
      if not isinstance(body,str) or not body.strip():return json_error(400,'empty message')
      with core.tx() as c:
       c.execute('INSERT INTO messages(channel_id,author_id,body,created_at) VALUES(?,?,?,?)',(ch['id'],u['id'],body,core.now_iso()));i=c.lastrowid;x=c.execute('SELECT * FROM messages WHERE id=?',(i,)).fetchone());core.emit_event(c,ch['id'],'message.created',{'message':msg(x)})
      return web.json_response({'message':msg(x)},status=201)
    c=core.connect(); rows=c.execute('SELECT * FROM messages WHERE channel_id=? AND parent_id IS NULL AND deleted=0 ORDER BY id DESC',(ch['id'],)).fetchall();c.close();return web.json_response({'messages':[msg(x) for x in rows],'next_cursor':None})
async def ws(r):
    u=core.user_for_token(r.query.get('token')); 
    if not u:return json_error(401,'unauthorized')
    q=web.WebSocketResponse();await q.prepare(r); subs={}; 
    async def pump():
      while not q.closed:
       for cid,last in list(subs.items()):
        for e in core.events_after(cid,last): await q.send_json(e);subs[cid]=e['event_id']
       await asyncio.sleep(.05)
    task=asyncio.create_task(pump())
    try:
     async for m in q:
      if m.type==WSMsgType.TEXT:
       d=json.loads(m.data);cid=int(d.get('channel_id',0))
       if d.get('type')=='subscribe':subs[cid]=core.head_event_id(cid);await q.send_json({'type':'subscribed','channel_id':cid,'head_event_id':subs[cid]})
       elif d.get('type')=='resume':subs[cid]=int(d.get('since_event_id',0));await q.send_json({'type':'resumed','channel_id':cid,'head_event_id':core.head_event_id(cid)})
    finally:task.cancel()
    return q
app=web.Application()
app.router.add_get('/api/health',health);app.router.add_post('/api/auth/register',register);app.router.add_post('/api/auth/login',login);app.router.add_get('/api/auth/me',me)
app.router.add_get('/api/workspaces',workspaces);app.router.add_post('/api/workspaces',create_workspace);app.router.add_get('/api/workspaces/{slug}',workspace);app.router.add_post('/api/workspaces/{slug}/channels',channels)
app.router.add_post('/api/channels/{id}/join',join);app.router.add_route('*','/api/channels/{id}/messages',messages);app.router.add_get('/api/ws',ws)
app.router.add_get('/{path:.*}',lambda r:web.FileResponse('/app/static/index.html') if os.path.exists('/app/static/index.html') else web.Response(text='Huddle'))
web.run_app(app,host='127.0.0.1',port=8000+NODE)
